"""agents.py — the model as a callable, PROVIDED COMPLETE.

An `Agent` is a script, not a model: attempt 1, 2, 3 … are the entries of its
plan, and a plan that runs out repeats its last entry. It answers a `Reply` —
the text it produced, and what the call cost in tokens — and `calls` counts how
many times it was invoked, which is what a rework check asserts ("the node was
called twice, not once and not three times").

What the text *means* is not this file's business. `VERDICTS` is what a reviewer
may say and `APPROVALS` is what a human may say, and turning a `Reply` into
"accepted", "rework", "denied" or "failed" is stage 5's and stage 7's. What the
call *cost* is this file's business: `Reply.tokens` is an int — the budget in
stage 8 spends exactly this number — so nothing here ever builds a float.

Every factory takes `tokens=`: what one call of that script costs. It defaults
to `DEFAULT_TOKENS` (nothing), so a script that is supposed to spend has to be
told what it spends — `worker("index the pages", tokens=32)`.

Nothing here reads a clock, a network or a file, and nothing here is module
level state: an `Agent` counts its own calls, the factories build fresh ones,
and two runs of the same script answer the same bytes.
"""

from dataclasses import dataclass
import types

#: What one call of a script costs when the script does not say: nothing.
DEFAULT_TOKENS = 0

#: What a reviewer may say about a result. Anything that is not one of these
#: two texts is not a verdict, and a result is never accepted on a guess.
VERDICTS = ("accept", "reject")

#: What a human may say about an effect. Anything that is not one of these two
#: texts is not an approval, and an effect is never dispatched on a guess.
APPROVALS = ("approve", "deny")


class AgentError(ValueError):
    """A script, a plan or an answer the model refuses.

    The model's own refusal — a verdict outside `VERDICTS`, an approval outside
    `APPROVALS`, an empty plan, a shape `bad_shape` does not have, an attempt
    that is not a positive int — travels as this type, so a check can tell "your
    script is wrong" from "the work went wrong".
    """


def _require_int(value, what, *, minimum=0):
    """The house guard: a bool is not an int, and neither is a string."""
    if isinstance(value, bool) or not isinstance(value, int):
        raise AgentError("%s must be an int, got %r" % (what, value))
    if value < minimum:
        raise AgentError("%s must be >= %d, got %r" % (what, minimum, value))
    return value


def _require_text(value, what):
    """The other half of the guard: a script answers strings."""
    if not isinstance(value, str):
        raise AgentError("%s must be a string, got %r" % (what, value))
    return value


@dataclass(frozen=True)
class Reply:
    """What an agent answered: its text, and what the call cost.

    `tokens` is money: stage 8 spends exactly this number, so it is an int and
    never a float. It is *not* the verdict — a verdict lives in `text`, and a
    reply read from its tokens is the mistake stage 5 exists to prevent.

    The record is frozen but not policed: `Reply` is what a well-formed answer
    is, and an answer that is not one — a bare string, a record with no
    `tokens`, a negative cost — is built by `bad_shape` and refused by the
    caller, not by this class.
    """

    text: str
    tokens: int = DEFAULT_TOKENS


class Agent:
    """A scripted agent: `agent(prompt, *, attempt=1) -> Reply`.

    `calls` counts invocations and `attempts` counts them per prompt, which is
    what a rework check asserts ("the node was called twice, not once and not
    three times"). The agent never reads the clock and never guesses: it answers
    what its plan says for that attempt.

    An answer is passed through exactly as the script gives it — an agent that
    answers something that is not a `Reply` (`bad_shape`) is a defect the caller
    has to refuse, not one this class hides by inventing a reply.
    """

    def __init__(self, fn, *, label=None):
        if not callable(fn):
            raise AgentError("Agent needs a callable, got %r"
                             % (type(fn).__name__,))
        self._fn = fn
        self.label = label or getattr(fn, "__name__", "agent")
        self.calls = 0
        self.attempts = {}

    def __call__(self, prompt, *, attempt=1):
        _require_int(attempt, "attempt", minimum=1)
        key = prompt if isinstance(prompt, str) else repr(prompt)
        self.calls += 1
        self.attempts[key] = self.attempts.get(key, 0) + 1
        return self._fn(prompt, attempt)

    def __repr__(self):
        return "<Agent %s calls=%d>" % (self.label, self.calls)


def _script(steps, *, label, tokens):
    """A plan of `steps`, one per attempt, repeating its last entry: the
    scheduler's script, with the cost every call of it reports."""
    steps = tuple(steps)
    if not steps:
        raise AgentError("%s() needs at least one entry" % (label,))
    for step in steps:
        _require_text(step, "%s() entry" % (label,))

    def fn(prompt, attempt):
        step = steps[min(attempt, len(steps)) - 1]
        return Reply(step, tokens)
    return Agent(fn, label=label)


def _verdict_script(steps, allowed, *, label, tokens):
    """The same plan, with every entry checked against what that actor may say:
    a reviewer that can answer "maybe" is a graph nobody can decide."""
    steps = tuple(steps)
    if not steps:
        raise AgentError("%s() needs at least one verdict" % (label,))
    for verdict in steps:
        if verdict not in allowed:
            raise AgentError("%s(%s): %r is not one of %r"
                             % (label, ", ".join(repr(step) for step in steps),
                                verdict, allowed))
    return _script(steps, label=label, tokens=tokens)


def planner(*texts, tokens=DEFAULT_TOKENS):
    """A planner, scripted by attempt: attempt 1 answers `texts[0]`, attempt 2
    answers `texts[1]`, and a plan that runs out repeats its last entry."""
    _require_int(tokens, "tokens")
    return _script(texts, label="planner", tokens=tokens)


def worker(*texts, tokens=DEFAULT_TOKENS):
    """A worker, scripted by attempt, like fleet's `scripted`:
    `worker("index 12 files")` answers the same thing on every attempt."""
    _require_int(tokens, "tokens")
    return _script(texts, label="worker", tokens=tokens)


def reviewer(*verdicts, tokens=DEFAULT_TOKENS):
    """A reviewer, scripted by attempt, in `VERDICTS`: `reviewer("reject",
    "accept")` rejects the first attempt and accepts the rework."""
    _require_int(tokens, "tokens")
    return _verdict_script(verdicts, VERDICTS, label="reviewer", tokens=tokens)


def approver(*verdicts, tokens=DEFAULT_TOKENS):
    """A human, scripted by attempt, in `APPROVALS`: `approver("deny",
    "approve")` denies the first ask and approves the second."""
    _require_int(tokens, "tokens")
    return _verdict_script(verdicts, APPROVALS, label="approver", tokens=tokens)


def flaky_agent(*texts, failures=2, tokens=DEFAULT_TOKENS):
    """A script that fails the first `failures` attempts and then works: attempt
    `failures + 1` answers `texts[0]`, the next `texts[1]`, and so on.

    A failed attempt answers `"reject"` — in this course what a bad call looks
    like is an answer that is not an acceptance — so `flaky_agent("accept",
    failures=2)` rejects twice and accepts the third attempt, which is how far
    `MAX_REWORK` lets a node go. Every attempt costs `tokens`, the failures
    included: the call happened.
    """
    _require_int(failures, "failures")
    _require_int(tokens, "tokens")
    steps = tuple(texts)
    if not steps:
        raise AgentError("flaky_agent() needs at least one entry")
    for step in steps:
        _require_text(step, "flaky_agent() entry")

    def fn(prompt, attempt):
        if attempt <= failures:
            return Reply("reject", tokens)
        return Reply(steps[min(attempt - failures, len(steps)) - 1], tokens)
    return Agent(fn, label="flaky_agent")


def refuser(reason, *, tokens=DEFAULT_TOKENS):
    """An actor that never accepts: every attempt answers `reason` — the text a
    reviewer that rejects puts in its `Reply`, and the reason a rework prompt
    carries back to the node."""
    _require_text(reason, "refuser() reason")
    _require_int(tokens, "tokens")

    def fn(prompt, attempt):
        return Reply(reason, tokens)
    return Agent(fn, label="refuser")


def bad_shape(shape="string"):
    """An agent that answers something that is not a `Reply` at all, so the
    caller has to refuse the answer instead of filing it as a success:

    `string`     the whole answer is a `str`, not a record;
    `no_tokens`  a record without the `tokens` field;
    `bad_tokens` a `tokens` that is not an int;
    `negative`   a negative cost, which no call can have.
    """
    shapes = {
        "string": lambda prompt, attempt: "done",
        "no_tokens": lambda prompt, attempt: types.SimpleNamespace(text="done"),
        "bad_tokens": lambda prompt, attempt: Reply("done", "0"),
        "negative": lambda prompt, attempt: Reply("done", -1),
    }
    if shape not in shapes:
        raise AgentError("bad_shape(%r): want one of %r" % (shape, tuple(shapes)))
    return Agent(shapes[shape], label="bad_shape_%s" % shape)

files.fleet.py:
"""fleet.py — the clock, the tasks and the workers, PROVIDED COMPLETE.

This is J1's `lab.py`/`isa.py`: the thing under test and the things that fail. A
task queue is a machine that decides *when* other people's work runs, and then
has to say something true about what it did, so the domain here is deliberately
hostile: tasks that cost one tick and tasks that cost twelve, workers that are
slower than the estimate, workers that fail on the third attempt, workers that
die holding the slot and never come back, and a worker that reports a shape
nobody asked for.

Everything in this file is deterministic. There is no `threading`, no `time`, no
`random`, no `os`, no network, and no module-level mutable state: the "clock" is
a counter (`Clock`) that **the queue** advances, so a wait, a lease and a backoff
are properties of the code under test and not of the machine it ran on.

A worker here is a *pure function* of a task and an attempt: it answers with a
status and the number of ticks the task costs, and it never touches the clock.
That is the whole point of the model — the scheduler is a data structure, so two
runs of the same pool over the same tasks are the same run, byte for byte.

Nothing here knows about admission, ordering, concurrency limits, leases,
retries, dead letters, backpressure, ageing or records — that is the course.
"""

from dataclasses import dataclass
import types

#: What one task costs when it does not say.
DEFAULT_TICKS = 3

#: What one task is worth when it does not say (higher is served first).
DEFAULT_PRIORITY = 5

#: The default tenant: what a task is billed to, and what ages.
DEFAULT_TENANT = "batch"

#: The three things a worker can report about a task it was given.
#: `ok` and `failed` are finished (one succeeded, one did not); `died` is a task
#: that never finished — the worker is gone and the queue has to get it back.
OUTCOMES = ("ok", "failed", "died")

#: The raw task catalogue: the shape a job file carries, before anything
#: validates it. `ticks` is what the task costs a worker that runs it.
TASKS = types.MappingProxyType({
    "render": {"id": "render", "ticks": 3, "priority": 5, "tenant": "batch"},
    "index": {"id": "index", "ticks": 7, "priority": 1, "tenant": "batch"},
    "notify": {"id": "notify", "ticks": 1, "priority": 9, "tenant": "interactive"},
    "train": {"id": "train", "ticks": 12, "priority": 3, "tenant": "batch"},
    "audit": {"id": "audit", "ticks": 5, "priority": 5, "tenant": "compliance"},
    "purge": {"id": "purge", "ticks": 2, "priority": 7, "tenant": "compliance"},
    "digest": {"id": "digest", "ticks": 4, "priority": 6, "tenant": "interactive"},
    "publish": {"id": "publish", "ticks": 3, "priority": 9, "tenant": "interactive"},
})

#: The raw pool catalogue: the shape a pool config carries, before anything
#: validates it. `capacity` is how many tasks the queue will hold; the water
#: marks are the depths at which a policy starts and stops refusing.
POOLS = types.MappingProxyType({
    "small": {"id": "small", "max_concurrency": 1, "capacity": 4,
              "high_water": 3, "low_water": 1},
    "narrow": {"id": "narrow", "max_concurrency": 2, "capacity": 6,
               "high_water": 5, "low_water": 2},
    "wide": {"id": "wide", "max_concurrency": 4, "capacity": 16,
             "high_water": 12, "low_water": 4},
})


class QueueError(ValueError):
    """A spec, a pool, a task or a policy the queue refuses.

    The queue's own refusal (a typo in a spec, a task that is not a task, a
    limit that is already gone) travels as this type, so a check can tell "your
    configuration is wrong" from "the work failed".
    """


def _require_int(value, what, *, minimum=0):
    """The house guard: a bool is not an int, and neither is a string."""
    if isinstance(value, bool) or not isinstance(value, int):
        raise QueueError("%s must be an int, got %r" % (what, value))
    if value < minimum:
        raise QueueError("%s must be >= %d, got %r" % (what, minimum, value))
    return value


class Clock:
    """The injected clock: a counter, not a wall clock.

    A tick is one unit of work. The only thing that moves the value is `tick()`,
    and in this course the only caller is the queue: workers report what a task
    costs and the scheduler charges it.
    """

    def __init__(self, start=0):
        self._value = _require_int(start, "Clock start")
        self.ticks = 0

    def now(self):
        """The current reading."""
        return self._value

    def tick(self, n=1):
        """Advance by `n` ticks and return the new reading."""
        _require_int(n, "tick(n): n")
        self._value += n
        self.ticks += n
        return self._value

    def __repr__(self):
        return "Clock(now=%d, ticks=%d)" % (self._value, self.ticks)


@dataclass(frozen=True)
class TaskSpec:
    """A task the way `parse_task` will build one: an attribute bag, not a
    student type, so a check can fill a queue without importing stage 1."""

    id: str
    ticks: int = DEFAULT_TICKS
    priority: int = DEFAULT_PRIORITY
    tenant: str = DEFAULT_TENANT


@dataclass(frozen=True)
class PoolSpec:
    """A pool the way `parse_pool` will build one."""

    id: str
    max_concurrency: int = 1
    capacity: int = 4
    high_water: int = 3
    low_water: int = 1


def make_task(id, *, ticks=None, priority=None, tenant=None):
    """A task spec by id, out of `TASKS` unless overridden. A field the shape
    does not have is refused here, not ignored: the fixtures teach the same
    lesson as the course."""
    base = dict(TASKS.get(id, {"id": id}))
    base.update({"id": id})
    for key, value in (("ticks", ticks), ("priority", priority), ("tenant", tenant)):
        if value is not None:
            base[key] = value
    return TaskSpec(**base)


def make_pool(id="small", *, max_concurrency=None, capacity=None,
              high_water=None, low_water=None):
    """A pool spec by id, out of `POOLS` unless overridden."""
    base = dict(POOLS.get(id, {"id": id}))
    base["id"] = id
    for key, value in (("max_concurrency", max_concurrency), ("capacity", capacity),
                       ("high_water", high_water), ("low_water", low_water)):
        if value is not None:
            base[key] = value
    return PoolSpec(**base)


def outcome(status, ticks=0, detail=""):
    """The dict a worker answers with. Build one rather than spelling the keys."""
    return {"status": status, "ticks": ticks, "detail": detail}


class Worker:
    """A scripted worker: `worker(task, *, attempt=1) -> outcome`.

    `calls` counts invocations, which is what a retry check asserts ("the task
    was attempted twice, not once and not three times"). The worker never moves
    the clock: it answers with the ticks the task costs and the scheduler
    charges them.
    """

    def __init__(self, fn, *, label=None):
        if not callable(fn):
            raise QueueError("Worker needs a callable, got %r" % (type(fn).__name__,))
        self._fn = fn
        self.label = label or getattr(fn, "__name__", "worker")
        self.calls = 0
        self.attempts = {}

    def __call__(self, task, *, attempt=1):
        _require_int(attempt, "attempt", minimum=1)
        task_id = getattr(task, "id", task)
        self.calls += 1
        self.attempts[task_id] = self.attempts.get(task_id, 0) + 1
        answer = self._fn(task, attempt)
        if isinstance(answer, dict) and "status" in answer:
            return answer
        return answer

    def __repr__(self):
        return "<Worker %s calls=%d>" % (self.label, self.calls)


def _ticks_of(task, factor=1):
    ticks = getattr(task, "ticks", DEFAULT_TICKS)
    return ticks * factor


def reliable(*, factor=1, detail=""):
    """Does the work and reports it: `ok`, at the task's cost (times `factor`)."""
    def fn(task, attempt):
        return outcome("ok", _ticks_of(task, factor), detail or "done")
    return Worker(fn, label="reliable")


def instant():
    """Reports `ok` while costing *no* ticks — a task that is not really work."""
    def fn(task, attempt):
        return outcome("ok", 0, "nothing to do")
    return Worker(fn, label="instant")


def sluggish(*, factor=3):
    """Always slower than the estimate, and honest about it."""
    def fn(task, attempt):
        return outcome("ok", _ticks_of(task, factor), "slow but correct")
    return Worker(fn, label="sluggish")


def flaky(*, failures=2, cost=None):
    """Fails the first `failures` attempts, then does the work."""
    def fn(task, attempt):
        if attempt <= failures:
            return outcome("failed", _ticks_of(task, cost or 1),
                           "attempt %d failed" % attempt)
        return outcome("ok", _ticks_of(task), "succeeded on attempt %d" % attempt)
    return Worker(fn, label="flaky")


def crasher(*, on_attempt=3):
    """Succeeds until `on_attempt`, which it fails — the classic poison task."""
    def fn(task, attempt):
        if attempt == on_attempt:
            return outcome("failed", _ticks_of(task), "crashed on attempt %d" % attempt)
        return outcome("ok", _ticks_of(task), "fine")
    return Worker(fn, label="crasher")


def dying(*, on_attempt=2, ticks=None):
    """Dies on `on_attempt`: it never finishes, and the slot it held must come
    back to the queue — that is the lease the course has to honour."""
    def fn(task, attempt):
        if attempt == on_attempt:
            return outcome("died", _ticks_of(task) if ticks is None else ticks,
                           "the worker went away")
        return outcome("ok", _ticks_of(task), "fine")
    return Worker(fn, label="dying")


def always(status, *, ticks=None):
    """Answers the same thing every time. `always("died")` is a pool that
    cannot make progress, and a queue that must notice rather than spin."""
    def fn(task, attempt):
        cost = _ticks_of(task) if ticks is None else ticks
        return outcome(status, cost, "always %s" % status)
    return Worker(fn, label="always_%s" % status)


def scripted(plan, *, ticks=None):
    """A worker whose attempt 1, 2, ... are `plan` — `scripted(["died", "ok"])`
    dies once and then succeeds; a plan that runs out repeats its last entry."""
    steps = tuple(plan)
    if not steps:
        raise QueueError("scripted() needs at least one status")
    for status in steps:
        if status not in OUTCOMES:
            raise QueueError("scripted(%r): %r is not one of %r"
                             % (plan, status, OUTCOMES))

    def fn(task, attempt):
        status = steps[min(attempt, len(steps)) - 1]
        cost = _ticks_of(task) if ticks is None else ticks
        return outcome(status, cost, "attempt %d: %s" % (attempt, status))
    return Worker(fn, label="scripted")


def bad_shape(shape="string"):
    """A worker that reports something that is not an outcome at all, so the
    queue has to refuse it instead of filing it as a success."""
    shapes = {
        "string": lambda task, attempt: "ok",
        "no_ticks": lambda task, attempt: {"status": "ok"},
        "bad_status": lambda task, attempt: {"status": "fine", "ticks": 1},
        "negative": lambda task, attempt: {"status": "ok", "ticks": -1},
    }
    if shape not in shapes:
        raise QueueError("bad_shape(%r): want one of %r" % (shape, tuple(shapes)))
    return Worker(shapes[shape], label="bad_shape_%s" % shape)


def catalogue(*ids, **overrides):
    """The raw catalogue entries for `ids` as task specs — `catalogue("render",
    "index")` is the usual fixture for a whole run."""
    return [make_task(task_id, **overrides) for task_id in ids]
